const item = $input.first().json;

function slugify(value) {
  return String(value || '')
    .trim()
    .toLowerCase()
    .replace(/&/g, 'and')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function normalizeText(value) {
  return String(value || '')
    .trim()
    .toLowerCase();
}

const isGlw = String(item.source_mode || '').toLowerCase() === 'glw';

/*
 * Canonical WordPress product mappings.
 */
const productMap = {
  'led video walls': 'direct-view-led-video-walls',
  'direct view led video walls': 'direct-view-led-video-walls',
  'direct-view led video walls': 'direct-view-led-video-walls',

  'led wall rental': 'direct-view-led-video-walls',
  'led wall rentals': 'direct-view-led-video-walls',
  'led video wall rental': 'direct-view-led-video-walls',
  'led video wall rentals': 'direct-view-led-video-walls',

  'outdoor led displays': 'outdoor-led-displays',
  'church led walls': 'church-led-walls',
  'trade show led displays': 'trade-show-led-displays',
  'transparent led displays': 'transparent-led-displays',
  'creative led displays': 'creative-led-displays',
  'interactive led floors': 'interactive-led-floors',
  'led posters': 'led-posters',
  'custom led displays': 'custom-led-displays',

  'cob all-in-one led displays': 'cob-all-in-one-led-displays',
  'cob all in one led displays': 'cob-all-in-one-led-displays',

  'smd all-in-one led displays': 'smd-all-in-one-led-displays',
  'smd all in one led displays': 'smd-all-in-one-led-displays',

  'exhibition led displays': 'exhibition-led-displays',

  'flexible rollable led displays': 'flexible-rollable-led',
  'flexible and rollable led displays': 'flexible-rollable-led',
  'flexible & rollable led': 'flexible-rollable-led',
  'flexible and rollable led': 'flexible-rollable-led',

  'led fan displays': 'led-fans',
  'led fans': 'led-fans'
};

const slugAliasMap = {
  'led-video-walls': 'direct-view-led-video-walls',
  'direct-view-led-video-walls': 'direct-view-led-video-walls',

  'led-wall-rental': 'direct-view-led-video-walls',
  'led-wall-rentals': 'direct-view-led-video-walls',
  'led-video-wall-rental': 'direct-view-led-video-walls',
  'led-video-wall-rentals': 'direct-view-led-video-walls',

  'outdoor-led-displays': 'outdoor-led-displays',
  'church-led-walls': 'church-led-walls',
  'trade-show-led-displays': 'trade-show-led-displays',
  'transparent-led-displays': 'transparent-led-displays',
  'creative-led-displays': 'creative-led-displays',
  'interactive-led-floors': 'interactive-led-floors',
  'led-posters': 'led-posters',
  'custom-led-displays': 'custom-led-displays',
  'cob-all-in-one-led-displays': 'cob-all-in-one-led-displays',
  'smd-all-in-one-led-displays': 'smd-all-in-one-led-displays',
  'exhibition-led-displays': 'exhibition-led-displays',
  'flexible-rollable-led': 'flexible-rollable-led',
  'led-fans': 'led-fans'
};

/*
 * These are page types, NOT product categories.
 */
const genericPageTypes = new Set([
  'city_service',
  'city-service',
  'city',
  'state',
  'state_service',
  'state-service',
  'service',
  'location',
  'location_service',
  'location-service',
  'page_generation',
  'page-generation'
]);

/*
 * Always trust structured geographic fields.
 */
const stateSlug = slugify(item.state);
const citySlug = slugify(item.city);

/*
 * Try to resolve the canonical product.
 */
const productCandidates = [
  item.product,
  item.product_topic,
  item.productTopic,
  item.service,
  item.service_name,
  item.focus_keyword,
  item.focus_keyphrase
];

const pageTypeValue = normalizeText(item.page_type);

if (
  pageTypeValue &&
  !genericPageTypes.has(pageTypeValue)
) {
  productCandidates.push(item.page_type);
}

let productSlug = '';

for (const candidate of productCandidates) {
  const normalized = normalizeText(candidate);

  if (!normalized) {
    continue;
  }

  if (productMap[normalized]) {
    productSlug = productMap[normalized];
    break;
  }

  const candidateSlug = slugify(candidate);

  if (slugAliasMap[candidateSlug]) {
    productSlug = slugAliasMap[candidateSlug];
    break;
  }
}

/*
 * Existing product_slug fallback.
 */
if (!productSlug) {
  const existingProductSlug = slugify(item.product_slug);

  if (existingProductSlug && slugAliasMap[existingProductSlug]) {
    productSlug = slugAliasMap[existingProductSlug];
  }
}

/*
 * Raw slug fallback.
 *
 * IMPORTANT:
 * We may recover a recognized PRODUCT slug here.
 * We never recover state/city from item.slug.
 */
if (!productSlug) {
  const rawSlug = String(item.slug || '')
    .trim()
    .toLowerCase()
    .replace(/^\/+|\/+$/g, '');

  const parts = rawSlug
    .split('/')
    .map((part) => slugify(part))
    .filter(Boolean);

  for (const part of parts) {
    if (slugAliasMap[part]) {
      productSlug = slugAliasMap[part];
      break;
    }
  }
}

/*
 * LEGACY SHEET MODE
 *
 * Preserve prior behavior for old sheet/schedule rows.
 * Do not allow a legacy test row to break the entire workflow.
 */
if (!isGlw && !productSlug) {
  productSlug = slugify(item.page_type || item.product || '');
}

/*
 * GLW SAFETY GATES
 *
 * GLW is the production page-generation path.
 * It must never invent malformed hierarchy.
 */
if (isGlw && !productSlug) {
  throw new Error(
    [
      'GLW: Unable to resolve canonical product parent.',
      `page_type="${item.page_type || ''}"`,
      `category="${item.category || ''}"`,
      `focus_keyword="${item.focus_keyword || ''}"`,
      `product="${item.product || ''}"`,
      `product_topic="${item.product_topic || item.productTopic || ''}"`
    ].join(' ')
  );
}

if (isGlw && !stateSlug) {
  throw new Error(
    `GLW: Unable to resolve state slug from state="${item.state || ''}".`
  );
}

if (isGlw && !citySlug) {
  throw new Error(
    `GLW: Unable to resolve city slug from city="${item.city || ''}".`
  );
}

/*
 * For legacy sheet rows, preserve safe empty handling.
 */
const finalProductSlug = productSlug || '';
const finalStateSlug = stateSlug || '';
const finalCitySlug = citySlug || '';

const desiredHierarchicalSlug = [
  finalProductSlug,
  finalStateSlug,
  finalCitySlug
]
  .filter(Boolean)
  .join('/');

return [
  {
    json: {
      ...item,

      product_slug: finalProductSlug,
      state_slug: finalStateSlug,
      city_slug: finalCitySlug,

      desired_hierarchical_slug: desiredHierarchicalSlug
    }
  }
];

getRowsCode:
const input = $input.first().json;
const body =
  input.body && typeof input.body === 'object'
    ? input.body
    : input;

const isGlw = Boolean(
  body.jobId ||
  body.type === 'page_generation' ||
  body.page ||
  body.workflowContext ||
  body.publishingSettings
);

function slugify(value) {
  return String(value || '')
    .trim()
    .toLowerCase()
    .replace(/&/g, 'and')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function normalizePublishingMode(...values) {
  for (const value of values) {
    if (value === undefined || value === null || value === '') continue;

    const normalized = String(value).trim().toLowerCase();

    if (normalized === 'publish' || normalized === 'published') {
      return 'publish';
    }

    if (normalized === 'draft') {
      return 'draft';
    }
  }

  return isGlw ? 'publish' : 'draft';
}

if (!isGlw) {
  return [
    {
      json: {
        ...input,
        source_mode: 'sheet',
        publishing_mode: normalizePublishingMode(
          input.publishing_mode,
          input.publishingMode,
          input.status
        ),
        job_id: '',
        callback_url: ''
      }
    }
  ];
}

const page = body.page || {};
const site = body.site || {};
const publishingSettings =
  body.publishingSettings &&
  typeof body.publishingSettings === 'object'
    ? body.publishingSettings
    : {};

const workflowContext =
  body.workflowContext &&
  typeof body.workflowContext === 'object'
    ? body.workflowContext
    : {};

const seoSettings =
  body.seoSettings &&
  typeof body.seoSettings === 'object'
    ? body.seoSettings
    : {};

const product = String(
  page.product ||
  page.productTopic ||
  workflowContext.productTopic ||
  page.category ||
  seoSettings.category ||
  ''
).trim();

const category = String(
  page.category ||
  seoSettings.category ||
  page.product ||
  page.productTopic ||
  workflowContext.productTopic ||
  ''
).trim();

const state = String(
  page.state ||
  workflowContext.state ||
  ''
).trim();

const city = String(
  page.city ||
  workflowContext.city ||
  ''
).trim();

const focusKeyword = String(
  page.primaryKeyword ||
  seoSettings.primaryKeyword ||
  ''
).trim();

const jobId = String(
  body.jobId ||
  body.job_id ||
  ''
).trim();

const callbackUrl = String(
  body.callbackUrl ||
  body.callback_url ||
  ''
).trim();

if (!jobId) {
  throw new Error('GLW request is missing jobId.');
}

if (!product) {
  throw new Error(
    'GLW request is missing page.product, page.productTopic, workflowContext.productTopic, or page.category.'
  );
}

if (!focusKeyword) {
  throw new Error(
    'GLW request is missing page.primaryKeyword or seoSettings.primaryKeyword.'
  );
}

if (site.id && site.id !== 'led-display-warehouse') {
  throw new Error(`Unsupported GLW site: ${site.id}`);
}

const productSlug = slugify(
  page.productSlug ||
  page.targetSlug ||
  seoSettings.targetSlug ||
  product
);

const stateSlug = slugify(
  page.stateSlug ||
  state
);

const citySlug = slugify(
  page.citySlug ||
  seoSettings.citySlug ||
  seoSettings.city_slug ||
  workflowContext.citySlug ||
  city
);

const hierarchicalSlug = String(
  page.hierarchicalSlug ||
  page.hierarchical_slug ||
  seoSettings.hierarchicalSlug ||
  workflowContext.hierarchicalSlug ||
  ''
).trim();

const slugParts = hierarchicalSlug
  ? hierarchicalSlug
      .split('/')
      .map((part) => slugify(part))
      .filter(Boolean)
  : [productSlug, stateSlug, citySlug].filter(Boolean);

const requestedTitle = String(
  page.pageTitle ||
  page.page_title ||
  page.title ||
  ''
).trim();

const requestedH1 = String(
  page.h1 ||
  ''
).trim();

const wordCount = Number(
  publishingSettings.wordCount ||
  page.wordCount ||
  page.word_count ||
  1500
);

const additionalInstructions = String(
  page.additionalInstructions ||
  page.additional_instructions ||
  workflowContext.additionalInstructions ||
  workflowContext.additional_instructions ||
  ''
).trim();

const publishingMode = normalizePublishingMode(
  body.publishing_mode,
  body.publishingMode,
  publishingSettings.status,
  page.publishingMode,
  page.publishing_mode,
  page.status
);

return [
  {
    json: {
      source_mode: 'glw',
      job_id: jobId,
      callback_url: callbackUrl,

      publishing_mode: publishingMode,

      site_id: site.id || 'led-display-warehouse',
      site_name: site.name || 'LED Display Warehouse',

      page_type: String(
        page.page_type ||
        page.pageType ||
        workflowContext.pageType ||
        product
      ).trim(),

      category,
      state,
      city,
      focus_keyword: focusKeyword,

      slug: slugParts.join('/'),

      page_title: requestedTitle,
      h1: requestedH1,

      internal_links: '',

      word_count:
        Number.isFinite(wordCount) && wordCount > 0
          ? wordCount
          : 1500,

      additional_instructions: additionalInstructions,

      status: 'Ready',
      row_number: ''
    }
  }
];
